import jwt from"jsonwebtoken";import bcrypt from"bcrypt";let SECRET_KEY=process.env.JWT_SECRET;function gerarToken(r){if(SECRET_KEY)return r={id:r.id,email:r.email},jwt.sign(r,SECRET_KEY,{expiresIn:"7d"});throw new Error("JWT_SECRET não configurado no ambiente")}function extrairTokenDeCookie(r){return r?r.split(";").reduce((r,e)=>{var[e,o]=e.trim().split("=");return"token"===e||"AuthToken"===e?decodeURIComponent(o||""):r},null):null}function verificarToken(o,n,t){var r=o.headers.authorization;let e=r&&r.split(" ")[1];if(!(e=e||extrairTokenDeCookie(o.headers.cookie||"")))return n.status(401).json({erro:"Token não fornecido ou acesso negado."});jwt.verify(e,SECRET_KEY,(r,e)=>{if(r)return n.status(403).json({erro:"Token inválido ou expirado."});o.usuario=e,t()})}let saltRounds=10;async function criarHash(r){return bcrypt.hash(r,saltRounds)}async function compararSenha(r,e){return bcrypt.compare(r,e)}export{gerarToken,verificarToken,criarHash,compararSenha};